DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `title` varchar(255) NOT NULL,
  `message` text NOT NULL,
  `type` varchar(50) NOT NULL DEFAULT 'reminder',
  `is_read` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_notifications_user_read` (`user_id`,`is_read`,`created_at`),
  CONSTRAINT `fk_notifications_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table: password_resets
DROP TABLE IF EXISTS `password_resets`;
CREATE TABLE `password_resets` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `code_hash` varchar(255) NOT NULL,
  `expires_at` datetime NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_password_resets_user` (`user_id`,`expires_at`),
  CONSTRAINT `fk_password_resets_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table: peer_evaluations
DROP TABLE IF EXISTS `peer_evaluations`;
CREATE TABLE `peer_evaluations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `evaluator_id` int(10) unsigned DEFAULT NULL,
  `evaluator_user_id` int(10) unsigned DEFAULT NULL,
  `evaluatee_id` int(10) unsigned DEFAULT NULL,
  `course_id` int(10) unsigned DEFAULT NULL,
  `deadline` varchar(64) DEFAULT '2026-08-17',
  `status` enum('pending','active','submitted') NOT NULL DEFAULT 'pending',
  `submitted_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `dispatch_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_evaluator_evaluatee_pair` (`evaluator_id`,`evaluatee_id`),
  KEY `idx_evaluator_id` (`evaluator_id`),
  KEY `idx_evaluatee_id` (`evaluatee_id`),
  KEY `fk_peer_evaluations_course` (`course_id`),
  KEY `idx_peer_evaluations_evaluator_user` (`evaluator_user_id`),
  CONSTRAINT `fk_peer_evaluations_course` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_peer_evaluations_evaluatee` FOREIGN KEY (`evaluatee_id`) REFERENCES `instructors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_peer_evaluations_evaluator` FOREIGN KEY (`evaluator_id`) REFERENCES `instructors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_peer_evaluations_evaluator_user` FOREIGN KEY (`evaluator_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1033 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table: peer_evaluation_publications
DROP TABLE IF EXISTS `peer_evaluation_publications`;
CREATE TABLE `peer_evaluation_publications` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `department_id` int(10) unsigned NOT NULL,
  `academic_year` varchar(64) NOT NULL,
  `semester` varchar(64) NOT NULL,
  `status` enum('published','unpublished') NOT NULL DEFAULT 'unpublished',
  `started_at` datetime DEFAULT NULL,
  `created_by` int(10) unsigned NOT NULL,
  `published_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_peer_publication_term` (`department_id`,`academic_year`,`semester`),
  KEY `fk_peer_publication_creator` (`created_by`),
  CONSTRAINT `fk_peer_publication_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_peer_publication_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table: peer_evaluation_submissions
DROP TABLE IF EXISTS `peer_evaluation_submissions`;
CREATE TABLE `peer_evaluation_submissions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `peer_evaluation_id` int(10) unsigned NOT NULL,
  `evaluator_id` int(10) unsigned NOT NULL,
  `evaluatee_id` int(10) unsigned DEFAULT NULL,
  `score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `strengths` text DEFAULT NULL,
  `suggestions` text DEFAULT NULL,
  `responses` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`responses`)),
  `status` varchar(32) NOT NULL DEFAULT 'submitted',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_peer_evaluation_submissions_peer_eval` (`peer_evaluation_id`),
  KEY `fk_peer_evaluation_submissions_evaluator` (`evaluator_id`),
  KEY `fk_peer_evaluation_submissions_evaluatee` (`evaluatee_id`),
  CONSTRAINT `fk_peer_evaluation_submissions_evaluatee` FOREIGN KEY (`evaluatee_id`) REFERENCES `instructors` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_peer_evaluation_submissions_evaluator` FOREIGN KEY (`evaluator_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_peer_evaluation_submissions_peer_eval` FOREIGN KEY (`peer_evaluation_id`) REFERENCES `peer_evaluations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table: students
DROP TABLE IF EXISTS `students`;
CREATE TABLE `students` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `student_id` varchar(64) NOT NULL,
  `first_name` varchar(128) NOT NULL,
  `last_name` varchar(128) NOT NULL,
  `department_id` int(10) unsigned NOT NULL,
  `semester` varchar(32) NOT NULL,
  `year_level` varchar(32) NOT NULL,
  `section` varchar(32) NOT NULL,
  `gender` varchar(10) DEFAULT NULL,
  `phone_number` varchar(32) DEFAULT NULL,
  `profile_picture` varchar(255) DEFAULT NULL,
  `program_type` varchar(64) DEFAULT 'Regular',
  `registration_date` varchar(64) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  UNIQUE KEY `student_id` (`student_id`),
  KEY `fk_students_department` (`department_id`),
  CONSTRAINT `fk_students_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_students_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table: student_evaluations
DROP TABLE IF EXISTS `student_evaluations`;
CREATE TABLE `student_evaluations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` int(10) unsigned NOT NULL,
  `course_id` int(10) unsigned NOT NULL,
  `target_user_id` int(10) unsigned NOT NULL,
  `target_type` varchar(32) NOT NULL DEFAULT 'instructor',
  `evaluator_role` varchar(32) NOT NULL DEFAULT 'student_to_instructor',
  `score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `feedback` text DEFAULT NULL,
  `strengths` text DEFAULT NULL,
  `improvements` text DEFAULT NULL,
  `responses` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`responses`)),
  `status` varchar(32) NOT NULL DEFAULT 'submitted',
  `submitted_at` datetime NOT NULL DEFAULT current_timestamp(),
  `editable_until` datetime NOT NULL DEFAULT (current_timestamp() + interval 3 day),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_student_evaluation` (`student_id`,`course_id`,`target_user_id`,`target_type`),
  KEY `idx_student_evaluations_target` (`target_user_id`,`target_type`),
  KEY `idx_student_evaluations_course` (`course_id`),
  CONSTRAINT `fk_student_evaluations_course` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_student_evaluations_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_student_evaluations_target` FOREIGN KEY (`target_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table: student_evaluation_submissions
DROP TABLE IF EXISTS `student_evaluation_submissions`;
CREATE TABLE `student_evaluation_submissions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `dispatch_id` int(10) unsigned NOT NULL,
  `student_id` int(10) unsigned DEFAULT NULL,
  `student_name` varchar(255) DEFAULT NULL,
  `score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `feedback` text DEFAULT NULL,
  `responses` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`responses`)),
  `status` varchar(32) NOT NULL DEFAULT 'submitted',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `strengths` text DEFAULT NULL,
  `improvements` text DEFAULT NULL,
  `submitted_at` datetime NOT NULL DEFAULT current_timestamp(),
  `editable_until` datetime NOT NULL DEFAULT (current_timestamp() + interval 3 day),
  PRIMARY KEY (`id`),
  KEY `fk_student_evaluation_submissions_dispatch` (`dispatch_id`),
  KEY `fk_student_evaluation_submissions_student` (`student_id`),
  CONSTRAINT `fk_student_evaluation_submissions_dispatch` FOREIGN KEY (`dispatch_id`) REFERENCES `evaluation_dispatches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_student_evaluation_submissions_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=89 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table: system_settings
DROP TABLE IF EXISTS `system_settings`;
CREATE TABLE `system_settings` (
  `setting_key` varchar(128) NOT NULL,
  `setting_value` text DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table: template_criteria
DROP TABLE IF EXISTS `template_criteria`;
CREATE TABLE `template_criteria` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `template_id` int(10) unsigned NOT NULL,
  `category` varchar(255) NOT NULL,
  `position` int(11) NOT NULL DEFAULT 0,
  `criteria_key` varchar(255) DEFAULT NULL,
  `text_en` text DEFAULT NULL,
  `text_am` text DEFAULT NULL,
  `meta` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`meta`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_template_criteria_template_id` (`template_id`),
  KEY `idx_template_criteria_category` (`category`),
  CONSTRAINT `fk_template_criteria_template` FOREIGN KEY (`template_id`) REFERENCES `evaluation_templates` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table: users
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `email` varchar(255) DEFAULT NULL,
  `password_hash` varchar(255) NOT NULL,
  `role` enum('admin','student','instructor','dept_head','department_head','college_dean','dean','academic_directorate','academic_director','directorate','lab_assistant') NOT NULL DEFAULT 'student',
  `status` varchar(32) NOT NULL DEFAULT 'active',
  `is_first_login` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `student_id` varchar(50) DEFAULT NULL,
  `gender` varchar(10) DEFAULT NULL,
  `telegram_chat_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  KEY `fk_users_students` (`student_id`),
  CONSTRAINT `fk_users_students` FOREIGN KEY (`student_id`) REFERENCES `students` (`student_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=198 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

SET FOREIGN_KEY_CHECKS = 1;
